    # Obtener stock físico y reservado de un producto
    physical_stock, reserved_stock = get_inventory_product(product_id, location_id)
    return physical_stock, reserved_stock

def get_inventory_product(product_id, location_id=None):
    # Obtener stock físico y reservado de un producto
    inventory_product = {
        "P01": (10, 0),
        "P02": (0, 0),
        "P03": (0, 0)
    }
    if product_id in inventory_product:
        physical_stock, reserved_stock = inventory_product[product_id]
    else:
        physical_stock, reserved_stock = 0, 0
    if location_id is not None:
        physical_stock, reserved_stock = get_inventory_product(product_id, location_id)
    return physical_stock, reserved_stock

def atendida(product_id, quantity, location_id=None):
    # Atender una línea de pedido
    if product_id in inventory_product:
        physical_stock, reserved_stock = inventory_product[product_id]
        if quantity <= physical_stock:
            return True
        elif quantity <= reserved_stock:
            return True
        else:
            return False
    else:
        return False

def pendientes(product_id, quantity):
    # Calcular las unidades pendientes de una línea
    if product_id in inventory_product:
        physical_stock, reserved_stock = inventory_product[product_id]
        return physical_stock - quantity
    else:
        return 0

def puede_alcanzar(product_id, quantity, location_id=None):
    # Verificar si las líneas se pueden atender sin pedidos pendientes
    if product_id in inventory_product:
        physical_stock, reserved_stock = inventory_product[product_id]
        return atendida(product_id, quantity) and (pendientes(product_id, quantity) == 0 or quantity <= pendientes(product_id, quantity))
    else:
        return False

def puede_faltar(product_id, quantity, location_id=None):
    # Calcular las unidades faltantes de una línea
    if product_id in inventory_product:
        physical_stock, reserved_stock = inventory_product[product_id]
        return pendientes(product_id, quantity)
    else:
        return 0

